UPDATE pages SET blocks = JSON_SET(blocks,
  '$.additional_title',
  'Любовная магия: как вернуть гармонию в отношения',
  '$.additional_text',
  'Любовь — самая тонкая и уязвимая сфера человеческой жизни. Здесь сплетаются чувства, судьбы, родовые программы и порой намеренные негативные воздействия со стороны. Когда отношения, ещё вчера казавшиеся крепкими, вдруг рассыпаются на глазах, а одиночество затягивается на годы вопреки всем усилиям, это редко бывает случайностью. Это всегда повод задуматься и обратиться за грамотной помощью.\n\nНа официальном сайте «битва экстрасенсов» собраны специалисты с проверенным опытом, среди которых есть как практикующие маги, так и потомственные ведуньи. Каждая ведьма, работающая в команде проекта, проходит долгий путь обучения и умеет аккуратно настраивать тонкие связи между людьми. Это не «приворот любой ценой», а бережная и этичная работа: восстановление искренних чувств, снятие наведённого охлаждения, очищение пары от чужого влияния, гармонизация семейного эгрегора.\n\nКачественная помощь экстрасенса в любовных вопросах всегда начинается с честного разговора. Специалист задаёт уточняющие вопросы, проводит диагностику обоих партнёров (если речь о паре), смотрит причины — будь то остывание из-за усталости, последствия чужой ревности или влияние прошлых связей. Только после этого подбираются методы работы: ритуалы на возврат любви, обряды снятия одиночества, программы на встречу со своим человеком.\n\nПриём экстрасенса проводится в максимально комфортном для клиента формате — лично, по телефону или онлайн, с полным сохранением конфиденциальности. Никто не узнает о вашем обращении, а сам процесс выстроен так, чтобы вы чувствовали поддержку на каждом этапе. Если ваше сердце устало бороться в одиночку, а попытки «всё исправить самостоятельно» не приносят результата, доверьтесь специалисту. Запись на консультацию — это не слабость, а зрелое решение позаботиться о своём счастье и будущем.'
) WHERE page_slug = 'service-lyubovnaya-magiya';

