-- ─────────────────────────────────────────────────────────────────────
UPDATE pages SET blocks = JSON_SET(blocks,
  '$.additional_title',
  'Магическая защита: щит для человека, дома и семьи',
  '$.additional_text',
  'Магическая защита — это не «модный амулет» и не модная практика, а серьёзная многоуровневая работа, благодаря которой человек становится неуязвим для большинства внешних негативных воздействий. Зависть коллег, недобрые взгляды соседей, родовые проклятия, оставшиеся в наследство, целенаправленные наговоры — всё это реально влияет на здоровье, отношения и финансы. Грамотно поставленная защита убирает основной канал, через который негатив проникает в жизнь.\n\nПрограмма «экстрасенсы битва сильнейших», где встречаются самые опытные специалисты, наглядно показывает: настоящий маг не размахивает руками для эффекта, а работает тихо, точно и с пониманием механики тонкого мира. Опытный медиум видит каналы воздействия, чувствует, кто и зачем направил негатив, и подбирает индивидуальный комплекс защитных мер. Это не шаблон «один обряд на всех», а персональное решение для конкретной ситуации.\n\nКомплексная помощь экстрасенса в вопросах защиты включает несколько обязательных этапов. Сначала проводится диагностика: что уже «висит» на человеке, есть ли активные программы, кто их источник. Затем выполняется чистка — снятие негативных слоёв, отработка последствий. И только после этого ставится постоянная защита: на ауру, дом, машину, бизнес, близких. Дополнительно специалист обучает простым повседневным практикам, которые помогают поддерживать щит самостоятельно.\n\nОсобенно важно ставить защиту тем, кто работает с людьми (врачи, педагоги, бизнесмены, артисты), часто появляется на публике, разводится или, наоборот, переживает яркий этап взлёта — именно в такие периоды поток чужого внимания максимален. Если вы чувствуете беспричинную усталость, нарастающее раздражение в семье, череду «непонятных» болезней или странных совпадений, не откладывайте. Запишитесь на консультацию — и верните своему пространству безопасность, тишину и силу.'
) WHERE page_slug = 'service-magicheskaya-zashchita';

