UPDATE pages SET blocks = JSON_SET(blocks,
  '$.additional_title',
  'Снятие порчи: как распознать и устранить негативное воздействие',
  '$.additional_text',
  'Порча — одно из самых тяжёлых негативных воздействий, с которыми сталкивается человек. В отличие от случайного сглаза, она наводится намеренно и нередко передаётся через бытовые предметы, фотографии или прямой контакт. Последствия могут быть крайне разрушительны: внезапные болезни без диагноза, череда финансовых неудач, разрыв отношений, постоянное чувство тревоги, навязчивые мысли. Чем дольше порча остаётся неснятой, тем глубже она прорастает в судьбу.\n\nПроект «битва экстрасенсов» неоднократно показывал, насколько разрушительной может быть энергетическая атака — и как профессионально с ней работают сильные специалисты. Опытная ведьма с потомственным даром способна точно определить тип воздействия: бытовая порча, кладбищенская, на смерть, на разрыв, наведённая через подклад. От правильного определения зависит весь дальнейший план работы — универсальных «таблеток» здесь не бывает.\n\nГрамотная помощь экстрасенса в случае порчи всегда состоит из нескольких обязательных шагов. Сначала проводится диагностика — на свечу, воду, карты или иные проверенные инструменты. Опытный медиум видит не только сам факт воздействия, но и канал, по которому оно поступило, силу, давность, источник. Затем выполняется снятие: специалист разрывает связь с заказчиком и исполнителем, очищает ауру, возвращает энергии в нейтральное русло. После — обязательная защита, чтобы новая атака не вернулась.\n\nЕсли вы заметили у себя или близкого человека сразу несколько тревожных признаков (резкое ухудшение здоровья, постоянные ссоры, потеря желания жить, навязчивые сны), не стоит ждать «само пройдёт». Самостоятельные ритуалы из интернета без точной диагностики чаще усугубляют ситуацию, чем помогают. Запишитесь на консультацию к проверенному специалисту: профессиональное снятие порчи возвращает человеку здоровье, чувство опоры и спокойствия — а главное, восстанавливает естественный ход событий в его жизни.'
) WHERE page_slug = 'topic-porcha';

