UPDATE pages SET blocks = JSON_SET(blocks,
  '$.additional_title',
  'Снятие сглаза: возврат лёгкости и энергии в повседневной жизни',
  '$.additional_text',
  'Сглаз — наиболее частое негативное воздействие, с которым сталкивается практически каждый человек хотя бы раз в жизни. В отличие от порчи или проклятия, он, как правило, не наводится осознанно: достаточно зависти, восхищения «через край» или просто сильного эмоционального удара со стороны другого человека. Однако «несерьёзность» источника не делает сглаз безобидным. Он способен украсть силы, испортить настроение на недели, спровоцировать ссоры и сбить с толку даже самого устойчивого человека.\n\nЦикл «экстрасенсы реванш», как и сам проект «битва экстрасенсов», знаменит тем, что показывает: даже самые «невидимые» воздействия имеют чёткую структуру и поддаются устранению. Опытная ведьма видит сглаз буквально с первых минут общения с клиентом — по голосу, взгляду, состоянию ауры. Дальше всё дело техники: специалист определяет, кто и при каких обстоятельствах «зацепил», есть ли усиление или это разовое явление, и подбирает метод очищения.\n\nПрофессиональная помощь экстрасенса при сглазе обычно занимает гораздо меньше времени, чем работа с порчей или проклятием. Чаще достаточно одного-двух сеансов, чтобы человек снова почувствовал себя собой: вернулась бодрость, нормализовался сон, ушла беспричинная тревожность, начали складываться рабочие и семейные дела. В сложных случаях, когда сглаз «впитался» давно и оброс дополнительными слоями, работа выстраивается поэтапно.\n\nПризнаки, по которым стоит насторожиться: внезапная усталость без причины, частые головные боли «из ниоткуда», ссоры с близкими на пустом месте, череда мелких неудач, чувство, что «всё валится из рук». Особенно внимательно к себе и детям стоит относиться после праздников, шумных компаний, появления на людях с радостной новостью. Не игнорируйте интуицию: запишитесь на короткую диагностику. Своевременное снятие сглаза занимает несколько дней, а возвращает порой месяцы полноценной жизни.'
) WHERE page_slug = 'topic-sglaz';

